#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "cJSON.h"

static char *nested_array(size_t depth)
{
    size_t index;
    char *text = malloc(depth * 2 + 2);
    if (text == NULL) {
        return NULL;
    }
    for (index = 0; index < depth; ++index) {
        text[index] = '[';
    }
    text[depth] = '0';
    for (index = 0; index < depth; ++index) {
        text[depth + 1 + index] = ']';
    }
    text[depth * 2 + 1] = '\0';
    return text;
}

static int run_case(size_t depth)
{
    const char *parse_end = NULL;
    char *input = nested_array(depth);
    cJSON *value;
    size_t offset;
    if (input == NULL) {
        return 2;
    }
    value = cJSON_ParseWithOpts(input, &parse_end, 1);
    offset = parse_end == NULL ? 0 : (size_t)(parse_end - input);
    printf("depth=%zu result=%s parse_end=%zu input_len=%zu\n",
           depth, value == NULL ? "NULL" : "ok", offset, strlen(input));
    cJSON_Delete(value);
    free(input);
    return 0;
}

int main(void)
{
    /*
     * These depths are deliberately fixed instead of being derived from the
     * library macro.  That makes a future CJSON_NESTING_LIMIT change observable
     * rather than silently moving both the treatment and the test inputs.
     */
    static const size_t fixed_depths[] = {999u, 1000u, 1001u};
    size_t index;
    int status = 0;
    for (index = 0; index < sizeof(fixed_depths) / sizeof(fixed_depths[0]); ++index) {
        status |= run_case(fixed_depths[index]);
    }
    return status;
}

struct netif *
netif_add(struct netif *netif,
#if LWIP_IPV4
          const ip4_addr_t *ipaddr, const ip4_addr_t *netmask, const ip4_addr_t *gw,
#endif /* LWIP_IPV4 */
          void *state, netif_init_fn init, netif_input_fn input)
{
#if LWIP_IPV6
  s8_t i;
#endif

  LWIP_ASSERT_CORE_LOCKED();

#if LWIP_SINGLE_NETIF
  if (netif_default != NULL) {
    LWIP_ASSERT("single netif already set", 0);
    return NULL;
  }
#endif

  LWIP_ERROR("netif_add: invalid netif", netif != NULL, return NULL);
  LWIP_ERROR("netif_add: No init function given", init != NULL, return NULL);

/* call user specified initialization function for netif */
if (init(netif) != ERR_OK) {
  return NULL;
}
LWIP_ASSERT("netif->hwaddr_len <= NETIF_MAX_HWADDR_LEN",
            (netif->hwaddr_len <= NETIF_MAX_HWADDR_LEN));

  if (netif->num == 254) {
    netif_num = 0;
  } else {
    netif_num = (u8_t)(netif->num + 1);
  }

  /* add this netif to the list */
  netif->next = netif_list;
  netif_list = netif;
#endif /* "LWIP_SINGLE_NETIF */

netif_set_default(struct netif *netif)
{
  LWIP_ASSERT_CORE_LOCKED();

  if (netif == NULL) {
    /* remove default route */
    mib2_remove_route_ip4(1, netif);
  } else {
    /* install default route */
    mib2_add_route_ip4(1, netif);
  }
  netif_default = netif;
  LWIP_DEBUGF(NETIF_DEBUG, ("netif: setting default interface %c%c\n",
                            netif ? netif->name[0] : '\'', netif ? netif->name[1] : '\''));
}

#if LWIP_SINGLE_NETIF
#define NETIF_FOREACH(netif) if (((netif) = netif_default) != NULL)
#else /* LWIP_SINGLE_NETIF */
/** The list of network interfaces. */
extern struct netif *netif_list;
#define NETIF_FOREACH(netif) for ((netif) = netif_list; (netif) != NULL; (netif) = (netif)->next)
#endif /* LWIP_SINGLE_NETIF */
/** The default network interface. */
extern struct netif *netif_default;

#include <stdio.h>
#include <string.h>

#include "lwip/netif.h"

static err_t test_init(struct netif *netif)
{
    netif->name[0] = 'c';
    netif->name[1] = 'a';
    netif->mtu = 1500;
    return ERR_OK;
}

static err_t test_input(struct pbuf *packet, struct netif *netif)
{
    LWIP_UNUSED_ARG(packet);
    LWIP_UNUSED_ARG(netif);
    return ERR_OK;
}

static const char *which(const struct netif *value,
                         const struct netif *first,
                         const struct netif *second)
{
    if (value == NULL) {
        return "none";
    }
    if (value == first) {
        return "first";
    }
    if (value == second) {
        return "second";
    }
    return "other";
}

int main(void)
{
    struct netif first;
    struct netif second;
    memset(&first, 0, sizeof(first));
    memset(&second, 0, sizeof(second));

    printf("initial list=%s default=%s\n",
           which(netif_list, &first, &second), which(netif_default, &first, &second));
    printf("add_first=%s\n",
           netif_add_noaddr(&first, NULL, test_init, test_input) == &first ? "ok" : "failed");
    printf("after_first list=%s default=%s\n",
           which(netif_list, &first, &second), which(netif_default, &first, &second));
    netif_set_default(&first);
    printf("after_set_default list=%s default=%s\n",
           which(netif_list, &first, &second), which(netif_default, &first, &second));
    printf("add_second=%s\n",
           netif_add_noaddr(&second, NULL, test_init, test_input) == &second ? "ok" : "failed");
    printf("after_second list=%s default=%s\n",
           which(netif_list, &first, &second), which(netif_default, &first, &second));
    netif_remove(&second);
    netif_remove(&first);
    return 0;
}
